  ui_story_5063_50630802_49_dialog_content = "คุณรู้จักอัศวินคนนี้ไหม แพม?",
  ui_story_5063_50630802_50_dialog_content = "ใช่ค่ะ พ่อ ท่านหญิงอิริดอนเป็นเพื่อนของฉันที่ช่วยฉันเสียเรื่องปัญหาเมื่อเร็ว ๆ นี้ ในความเป็นจริง ฉันกำลังคิดจะเชิญเธอมาทานอาหารค่ำด้วยกัน...",
  ui_story_5063_50630802_51_dialog_content = "ไม่น่ามีปัญหาใช่ไหมครับพ่อ? เพราะว่าคุณสองคนดูเหมือนจะรู้จักกันอยู่แล้ว",
